import frappe

@frappe.whitelist()
def planned_target_card(annual_sales_target):
    value = frappe.db.get_value(
        "Annual Sales Target",
        annual_sales_target,
        "annual_target_amount"
    ) or 0

    return {
        "value": value,
        "fieldtype": "Currency",
        "route": ["Form", "Annual Sales Target", annual_sales_target]
    }
